// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PuttyV2} from "../src/PuttyV2.sol";

contract InvMutTest is Test {
    PuttyV2 c;

    // fallback so low-level ERC20 transfers from C to this address succeed with empty returndata
    fallback() external {}

    function setUp() public { c = new PuttyV2("", 0, address(this)); }

    function testFuzz_property(address to, address to2, uint256 duration, uint256 salt) public {
        vm.assume(to != address(0) && to != address(0xdead) && to.code.length == 0);
        vm.assume(to2 != address(0) && to2 != to);
        duration = bound(duration, 0, 9_000 days);
        salt = bound(salt, 0, type(uint248).max);

        // ERC1271 maker: any signature validates via the contract fallback path
        ERC1271Maker maker = new ERC1271Maker();

        address[] memory whitelist = new address[](0);
        address[] memory floorTokens = new address[](0);
        PuttyV2.ERC20Asset[] memory erc20Assets = new PuttyV2.ERC20Asset[](0);
        PuttyV2.ERC721Asset[] memory erc721Assets = new PuttyV2.ERC721Asset[](0);

        PuttyV2.Order memory order = PuttyV2.Order({
            maker: address(maker),
            isCall: false,
            isLong: false,
            baseAsset: address(this), // has code; its fallback makes low-level transfers succeed
            strike: 0,
            premium: 0,
            duration: duration,
            expiration: block.timestamp + 1_000_000,
            nonce: salt,
            whitelist: whitelist,
            floorTokens: floorTokens,
            erc20Assets: erc20Assets,
            erc721Assets: erc721Assets
        });

        bytes memory sig = new bytes(0);
        uint256[] memory floorIds = new uint256[](0);

        address filler = address(0xBEEF);
        vm.prank(filler);
        uint256 positionId = c.fillOrder(order, sig, floorIds);

        // first hop: filler transfers the position token to `to`
        vm.prank(filler);
        bool first;
        try c.transferFrom(filler, to, positionId) { first = true; } catch { first = false; }

        // general rule: once `to` owns the token, `to` can transfer it onward
        vm.prank(to);
        bool second;
        try c.transferFrom(to, to2, positionId) { second = true; } catch { second = false; }

        assertTrue(first ? second : true, "ownership did not move: new owner cannot transfer onward");
    }
}

// minimal ERC1271 counterparty: validates every signature
contract ERC1271Maker {
    function isValidSignature(bytes32, bytes memory) external pure returns (bytes4) {
        return this.isValidSignature.selector;
    }
}
